/* Bad: Animate layout properties */
.bad-animation {
  transition: top 0.3s, left 0.3s, width 0.3s;
}
/* Triggers layout → paint → composite every frame */
/* Expensive, causes jank */

/* Good: Animate transforms */
.good-animation {
  transform: translateX(0);
  transition: transform 0.3s;
}
/* Only triggers composite */
/* Cheap, smooth at 60fps */

/* Best: Use GPU acceleration */
.best-animation {
  transform: translate3d(0, 0, 0);
  will-change: transform;
}
/* GPU-accelerated layer */
/* Even better performance */

/* Smooth hover effects */
.button {
  transition: transform 0.2s ease-out, opacity 0.2s ease-out;
}

.button:hover {
  transform: translateY(-2px);
  opacity: 0.9;
}

/* Modal fade-in */
.modal {
  opacity: 0;
  transform: scale(0.9);
  transition: opacity 0.3s ease-out, transform 0.3s ease-out;
}

.modal.active {
  opacity: 1;
  transform: scale(1);
}

/* Slide-in sidebar */
.sidebar {
  transform: translateX(-100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.sidebar.open {
  transform: translateX(0);
}

function animateElement(element, duration) {
  const startTime = performance.now();
  const startX = 0;
  const endX = 100;

  function step(currentTime) {
    const elapsed = currentTime - startTime;
    const progress = Math.min(elapsed / duration, 1);

    // Easing function for smooth motion
    const eased = 1 - Math.pow(1 - progress, 3);

    const currentX = startX + (endX - startX) * eased;
    element.style.transform = `translateX(${currentX}px)`;

    if (progress < 1) {
      requestAnimationFrame(step);
    }
  }

  requestAnimationFrame(step);
}

// Usage
const element = document.getElementById('animate');
animateElement(element, 1000); // 1 second animation

/* Expensive: Large box shadows */
.expensive-shadow {
  box-shadow: 0 0 50px rgba(0, 0, 0, 0.5);
}

/* Better: Use pseudo-element for shadow */
.better-shadow {
  position: relative;
}
.better-shadow::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle, rgba(0,0,0,0.5) 0%, transparent 70%);
  z-index: -1;
}

/* Expensive: Large blur filter */
.expensive-blur {
  filter: blur(20px);
}

/* Better: Use backdrop-filter with hardware acceleration */
.better-blur {
  backdrop-filter: blur(20px);
}

/* Avoid: Complex gradients on large areas */
.expensive-gradient {
  background: linear-gradient(45deg, #ff0000, #00ff00, #0000ff);
}

/* Better: Use simple colors or smaller gradient areas */
.better-gradient {
  background: #3b82f6;
}

